
using System;
using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc.ModelBinding.Validation;

namespace BarangayDocumentTracking.Models
{
    public class DocumentRequest
    {
        public int Id { get; set; }

        // Automatically generated by the controller
        [Display(Name = "Request Number")]
        [ValidateNever]
        public string RequestNumber { get; set; } = string.Empty;

        // Selected document
        [Required(ErrorMessage = "Please select a document.")]
        [Display(Name = "Document")]
        public int DocumentId { get; set; }

        // Resident Information
        [Required(ErrorMessage = "Full name is required.")]
        [StringLength(200)]
        [Display(Name = "Full Name")]
        public string ResidentName { get; set; } = string.Empty;

        [Required(ErrorMessage = "Email address is required.")]
        [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
        [StringLength(200)]
        [Display(Name = "Email Address")]
        public string Email { get; set; } = string.Empty;

        [Required(ErrorMessage = "Address is required.")]
        [StringLength(300)]
        [Display(Name = "Complete Address")]
        public string Address { get; set; } = string.Empty;

        [StringLength(50)]
        [Display(Name = "Contact Number")]
        public string? ContactNumber { get; set; }

        [Required(ErrorMessage = "Purpose is required.")]
        [StringLength(500)]
        [Display(Name = "Purpose of Request")]
        public string Purpose { get; set; } = string.Empty;

        // Automatically assigned by the controller
        [ValidateNever]
        public string Status { get; set; } = "Pending";

        public DateTime RequestDate { get; set; }

        public DateTime? ProcessedDate { get; set; }

        // Relationship to Documents table
        [ValidateNever]
        public Document? Document { get; set; }
    }
}
